        QuestionOption(id: "B", text: "Physical: ethanol is a green solid while ethanoic acid is a purple gas. Chemical: ethanol turns red litmus blue while ethanoic acid has no effect.", isCorrect: false),
        QuestionOption(id: "C", text: "Physical: ethanol freezes at room temperature while ethanoic acid boils at 20°C. Chemical: both react identically with sodium bicarbonate.", isCorrect: false),
        QuestionOption(id: "D", text: "Physical: they have identical boiling points. Chemical: ethanol is an acid and ethanoic acid is an alkaline base.", isCorrect: false),
